package com.yilu.yinling.system.controller;
import com.yilu.yinling.ai.client.LlmRuntimeState; import com.yilu.yinling.ai.rag.VectorProperties; import com.yilu.yinling.common.response.Result; import java.util.Map; import javax.sql.DataSource; import org.springframework.beans.factory.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.context.annotation.Profile; import org.springframework.data.redis.connection.RedisConnectionFactory; import org.springframework.web.bind.annotation.*;
@RestController @Profile("!demo") @RequestMapping("/api/v1/system") public class HealthController { private final LlmRuntimeState llm; private final VectorProperties vector; private final ObjectProvider<DataSource> mysql; private final ObjectProvider<RedisConnectionFactory> redis; @Autowired public HealthController(LlmRuntimeState l,VectorProperties v,ObjectProvider<DataSource> m,ObjectProvider<RedisConnectionFactory> r){llm=l;vector=v;mysql=m;redis=r;} public HealthController(LlmRuntimeState l,VectorProperties v){this.llm=l;this.vector=v;this.mysql=null;this.redis=null;} @GetMapping("/health") public Result<Map<String,String>> health(){return Result.ok(Map.of("mysql",probeMysql(),"redis",probeRedis(),"vectorDB",probeVector(),"llm",llm.isAvailable()?"UP":"DEGRADED"));} private String probeMysql(){if(mysql==null)return "UNKNOWN";DataSource ds=mysql.getIfAvailable();if(ds==null)return "UNKNOWN";try(var c=ds.getConnection();var s=c.createStatement();var rs=s.executeQuery("SELECT 1")){return rs.next()?"UP":"DOWN";}catch(Exception e){return "DOWN";}} private String probeRedis(){if(redis==null)return "UNKNOWN";RedisConnectionFactory rf=redis.getIfAvailable();if(rf==null)return "UNKNOWN";try(var c=rf.getConnection()){return "PONG".equalsIgnoreCase(c.ping())?"UP":"DOWN";}catch(Exception e){return "DOWN";}} private String probeVector(){if(!"pgvector".equals(vector.getProvider()))return "MOCK";try(var c=java.sql.DriverManager.getConnection(vector.getPostgres().getUrl(),vector.getPostgres().getUsername(),vector.getPostgres().getPassword());var s=c.createStatement();var rs=s.executeQuery("SELECT 1")){return rs.next()?"UP":"DOWN";}catch(Exception e){return "DOWN";}} }
